head.script:
// 원본 : 없음 — $c.win.print 사용법 합성 가이드 (/ui/sample/template/SMPPRT10001.xml)

/*
 * 화면 동작
 * 1. 팝업 로딩시 호출 화면이 넘긴 안내문 데이터(제목·회사명·상장일·내용·종목 목록)를 DataMap·DataList 에 담아 보여 준다
 * 2. 「인쇄」 클릭시 $c.win.print() — 팝업 화면 전체를 캡처해 브라우저 인쇄 대화상자를 띄운다
 * 3. 「PDF 저장」 클릭시 $c.win.print({ type : "pdf", fileName }) — 팝업 화면 전체를 A4 PDF 로 내려받는다
 * 4. 「종목 목록만 PDF」 클릭시 $c.win.print({ type : "pdf", target : grp_printArea, orientation : "landscape" }) — 그리드 영역만 가로 PDF 로 내려받는다
 * 5. 「닫기」 클릭시 인쇄·저장 횟수를 호출 화면에 돌려주며 닫는다
 *
 * 담긴 패턴
 * - 부모 파라미터 수신 ($c.data.getParameter)
 * - 레이어 팝업 영역만 인쇄·PDF 저장 ($c.win.print — type / target / fileName / orientation 옵션)
 *   · 버튼 영역(btnbox)은 출력에서 빼고 싶으면 target 으로 본문 그룹을 지정한다(이 화면의 grp_printArea 처럼).
 *   · print 는 async 라 await 로 완료를 기다리고, 실패(라이브러리 미등록 등)는 진입점의 handleError 가 안내한다.
 *   · 라이브러리(/cm/js 의 html2canvas·html2pdf)는 config.xml 의 engine module 로 정적 로드된다 — 화면에서 로드하지 않는다.
 * - 자기 팝업 닫기 + 결과 반환 ($c.win.closePopup(callbackParam))
 *
 * 복사해서 쓰는 순서
 * 1. 파일명과 meta_screenId 를 실제 화면ID 로 변경
 * 2. dma_notice·dlt_items 와 표·그리드 마크업을 업무 항목으로 교체
 * 3. 필요 없는 출력 버튼은 함수와 마크업을 함께 삭제
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "SMPPRT10001";

// 화면 상태값 — 호출 화면에 돌려줄 실행 횟수
scwin.printCnt = 0;
scwin.pdfCnt = 0;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 21
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPPRT10001.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 21
 * @description 초기화. 호출 화면이 openPopup 의 3번째 인자로 넘긴 안내문 데이터를 화면에 담는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 받는 파라미터 이름
 * @param
 * @returns
 * @hidden N
*/
scwin.init = function () {
    const param = $c.data.getParameter() ?? {};

    dma_notice.set("title", param.title ?? "안내문");
    dma_notice.set("comNm", param.comNm ?? "");
    dma_notice.set("listDd", param.listDd ?? "");
    dma_notice.set("contn", param.contn ?? "");

    dlt_items.removeAll();

    if ($c.util.isArray(param.rows)) {
        dlt_items.setJSON(param.rows);
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_print_onclick
 * @author Inswave
 * @date 2026. 09. 21
 * @description 인쇄 버튼 클릭. 팝업 화면 전체를 캡처해 인쇄 대화상자를 띄운다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_print_onclick = async function (e) {
    try {
        await $c.win.print({ title : dma_notice.get("title") });

        scwin.printCnt++;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "SMPPRT10001.btn_print_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_pdf_onclick
 * @author Inswave
 * @date 2026. 09. 21
 * @description PDF 저장 버튼 클릭. 팝업 화면 전체를 A4 세로 PDF 로 내려받는다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_pdf_onclick = async function (e) {
    try {
        await $c.win.print({
            type : "pdf",
            fileName : dma_notice.get("title") + "_" + dma_notice.get("listDd") + ".pdf"
        });

        scwin.pdfCnt++;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "SMPPRT10001.btn_pdf_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_pdfGrid_onclick
 * @author Inswave
 * @date 2026. 09. 21
 * @description 종목 목록만 PDF 버튼 클릭. 그리드를 감싼 그룹(grp_printArea)만 가로 PDF 로 내려받는다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_pdfGrid_onclick = async function (e) {
    try {
        await $c.win.print({
            type : "pdf",
            target : grp_printArea,
            fileName : "종목목록_" + dma_notice.get("listDd") + ".pdf",
            orientation : "landscape"
        });

        scwin.pdfCnt++;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "SMPPRT10001.btn_pdfGrid_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_close_onclick
 * @author Inswave
 * @date 2026. 09. 21
 * @description 닫기 버튼 클릭. 인쇄·저장 횟수를 호출 화면에 돌려주며 팝업을 닫는다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_close_onclick = function (e) {
    try {
        $c.win.closePopup({ printCnt : scwin.printCnt, pdfCnt : scwin.pdfCnt });
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPPRT10001.btn_close_onclick" });
    }
};


///////// 4. 서브미션 콜백 영역 /////////


///////// 5. 일반/업무 함수 영역 /////////
